/* Silent Shadows Classic 0.1.31; embedded original assets. */
(()=>{const PACKED="";
// Build template. The builder supplies PACKED as a gzip/base64 JSON payload.
(() => {
  'use strict';
  const script = document.currentScript;
  if (!script?.src) throw new Error('Use a regular <script src="silent-shadows.js" defer></script> include.');
  const base = new URL('./', script.src);
  const cssUrl = new URL('silent-shadows.css?v=0.1.31', base).href;
  const workerUrl = new URL('silent-shadows-sw.js', base).href;
  const targetId = script.dataset.target;
  const requestedHeight = Number(script.dataset.height);
  const height = requestedHeight >= 200 && requestedHeight <= 4096 ? requestedHeight : 720;
  const moduleUrls = new Map(), assetUrls = new Map();
  let registrationPromise;

  function decode(value) {
    const binary = atob(value), bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    return bytes;
  }

  async function registerWorker() {
    if (!isSecureContext || !('serviceWorker' in navigator)) throw new Error('Offline installation needs HTTPS or localhost.');
    if (base.origin !== location.origin || !location.pathname.startsWith(base.pathname)) throw new Error('For offline installation, put the HTML page in the same folder as these game files, or below it.');
    const registration = await navigator.serviceWorker.register(workerUrl);
    if (!registration.active || registration.installing) await new Promise((resolve, reject) => {
      const worker = registration.installing ?? registration.waiting;
      if (!worker) { resolve(); return; }
      const timer = setTimeout(() => reject(new Error('The offline worker did not activate. Reload and try again.')), 20000);
      const check = () => {
        if (worker.state === 'activated') { clearTimeout(timer); resolve(); }
        if (worker.state === 'redundant') { clearTimeout(timer); reject(new Error('The offline worker could not install.')); }
      };
      worker.addEventListener('statechange', check); check();
    });
    return registration;
  }

  async function downloadOffline(status) {
    try {
      status.textContent = 'Preparing offline download...';
      const registration = await (registrationPromise ??= registerWorker());
      await new Promise((resolve, reject) => {
        const channel = new MessageChannel();
        const timer = setTimeout(() => { channel.port1.close(); reject(new Error('Offline download timed out.')); }, 180000);
        channel.port1.onmessage = ({data}) => {
          if (data.error) { clearTimeout(timer); channel.port1.close(); reject(new Error(data.error)); }
          else if (data.ready) { clearTimeout(timer); channel.port1.close(); status.textContent = 'Offline ready: this page and all three game files are saved.'; resolve(); }
          else status.textContent = `Saving and verifying game files ${data.done}/${data.total}...`;
        };
        registration.active.postMessage({type:'CACHE_GAME', page:location.href}, [channel.port2]);
      });
      await navigator.storage?.persist?.();
    } catch (error) {
      registrationPromise = null;
      status.textContent = `Offline download stopped: ${error.message}`;
    }
  }

  async function mount() {
    const target = targetId ? document.getElementById(targetId) : null;
    if (targetId && !target) throw new Error(`Silent Shadows target "${targetId}" was not found.`);
    const wrapper = document.createElement('div');
    wrapper.style.cssText = 'width:100%;max-width:858px;margin:0 auto;';
    const status = document.createElement('p');
    status.textContent = 'Loading Silent Shadows...'; status.setAttribute('role','status');
    wrapper.append(status);
    if (target) target.append(wrapper);
    else if (script.parentElement === document.head) document.body.append(wrapper);
    else script.insertAdjacentElement('afterend', wrapper);
    try {
      if (!('DecompressionStream' in globalThis)) throw new Error('This game needs a current browser with Compression Streams support.');
      const stream = new Blob([decode(PACKED)]).stream().pipeThrough(new DecompressionStream('gzip'));
      const payload = await new Response(stream).json();
      const mime = {bmp:'image/bmp',png:'image/png',jpg:'image/jpeg',gif:'image/gif',wav:'audio/wav',json:'application/json'};
      function assetUrl(relative) {
        const key = relative.replace(/^\.\//,'').replace(/^game\//,'');
        if (!assetUrls.has(key)) {
          const encoded = payload.assets[key];
          if (!encoded) throw new Error(`Missing packaged resource: ${key}`);
          assetUrls.set(key, URL.createObjectURL(new Blob([decode(encoded)], {type:mime[key.split('.').pop().toLowerCase()] ?? 'application/octet-stream'})));
        }
        return assetUrls.get(key);
      }
      function moduleUrl(key, visiting = new Set()) {
        if (moduleUrls.has(key)) return moduleUrls.get(key);
        if (visiting.has(key)) throw new Error(`Circular packaged module: ${key}`);
        visiting.add(key);
        let source = payload.modules[key];
        if (!source) throw new Error(`Missing packaged module: ${key}`);
        source = source.replace(/\bfrom\s*(['"])(\.[^'"]+)\1/g, (whole, quote, dependency) => {
          const resolved = new URL(dependency, 'https://package.invalid/'+key).pathname.slice(1);
          return `from ${JSON.stringify(moduleUrl(resolved, visiting))}`;
        });
        visiting.delete(key);
        const url = URL.createObjectURL(new Blob([source], {type:'text/javascript'}));
        moduleUrls.set(key, url); return url;
      }
      const frame = document.createElement('iframe');
      frame.title = 'Silent Shadows Classic game'; frame.width = '858'; frame.height = String(height);
      frame.allow = 'fullscreen'; frame.allowFullscreen = true; frame.setAttribute('data-silent-shadows','');
      frame.style.cssText = `display:block;width:100%;height:${height}px;border:0;background:#343d4c;`;
      function fitFrame(){
        const mobile=matchMedia('(pointer:coarse), (max-width:720px)').matches;
        // Explicit embed heights remain supported. The default follows phone
        // rotation and the visible area above the on-screen keyboard.
        const autoHeight=!(requestedHeight>=200&&requestedHeight<=4096)&&mobile;
        const viewport=window.visualViewport;
        const available=Math.max(200,(viewport?.height??innerHeight)-Math.max(0,frame.getBoundingClientRect().top-(viewport?.offsetTop??0)));
        frame.style.height=`${autoHeight?available:height}px`;
      }
      window.addEventListener('resize',fitFrame);
      window.visualViewport?.addEventListener('resize',fitFrame);
      frame.addEventListener('load', () => {
        frame.contentWindow.__silentShadowsPackage = {url:assetUrl, sourceUrl:new URL('src/app.js',base).href, search:location.search, downloadOffline};
        const entry = frame.contentDocument.createElement('script'); entry.type = 'module'; entry.src = moduleUrl('src/app.js');
        entry.addEventListener('error', () => { status.hidden = false; status.textContent = 'The packaged game could not start. Reload to try again.'; });
        frame.contentDocument.body.append(entry); status.hidden = true;fitFrame();
      }, {once:true});
      const shell = payload.shell.replace('./game/ui/mirage.jpg', assetUrl('ui/mirage.jpg'));
      frame.srcdoc = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><link rel="icon" href="data:,"><link rel="stylesheet" href="'+cssUrl.replace(/&/g,'&amp;').replace(/"/g,'&quot;')+'"><title>Silent Shadows Classic</title></head><body>'+shell+'</body></html>';
      wrapper.append(frame);
      fitFrame();
      registrationPromise = registerWorker(); registrationPromise.catch(() => { registrationPromise = null; });
    } catch (error) {
      status.textContent = `Silent Shadows could not load: ${error.message}`;
      console.error(error);
    }
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', () => void mount(), {once:true});
  else void mount();
})();

})();
